    // ── PHP config → JS ─────────────────────────────────────
    const VIDEO_ID       = 'ESuKsItGgV4rMAE';
    const VIDEOTYPE      = '0';
    const VIDEO_TITLE    = 'Campeones (2018).mp4';
    const VIDEO_STATUS   = 'active';
    const PLAY_SEED      = 'ZTFo8NTVp9Zn7Jq0ZTE2Yq0Rq0Ma4t3a4ZDZs2NDx70Ya4A0Nn7Ub5Nn7R8MTx75Ma4E5MTQ4Nd7';
    const PLAY_SIG       = 'Zq0Yc6Mq0Q5Na4Bq0YTQ1MDQ2ZTQb5YWY3ZTUb5OTo8o8NWU0YTx7b5M2Yb5MDQ0Nq0Ec6MDt30NDY4Y2Rr1Mq0Nr1Yn7Jo8MWMb5YWVo8Zt3';
