            thumbnail: json.thumbnail || ''
          };
        }
        const err = new Error(json.error || json.message || `Request failed (${res.status})`);
        err.type = json.type || null;
        throw err;
      }

      return json;
    }

    // ── State ───────────────────────────────────────────────
    let videoData = null;
    let jwInstance = null;
    let tracksData = [];        // [{track_name, track_url, hls_url|null}]
    let currentTrackIndex = 0;

    function show(id) {
      ['loadingState','errorState','pendingState','failedState','playerState'].forEach(s => {
        const el = document.getElementById(s);
        if (!el) return;
        if (s === 'pendingState') { el.classList.toggle('show', s === id); el.classList.toggle('hidden', s !== id); }
        else el.classList.toggle('hidden', s !== id);
      });
    }

    function formatBytes(b) {
      if (!b) return '';
      const k = 1024, s = ['B','KB','MB','GB'];
      const i = Math.floor(Math.log(b) / Math.log(k));
      return (b / Math.pow(k, i)).toFixed(2) + ' ' + s[i];
    }

    function formatDuration(secs) {
      if (!secs) return '';
      const h = Math.floor(secs / 3600);
      const m = Math.floor((secs % 3600) / 60);
      const s = Math.floor(secs % 60);
      return h > 0
        ? `${h}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`
        : `${m}:${String(s).padStart(2,'0')}`;
    }

    function escHtml(str) {
      return String(str).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
    }

    // ── Centered player notice ───────────────────────────────
    let _noticeTimer = null;
