    function closeLangPicker() {
      document.getElementById('langPickerMenu').classList.add('hidden');
      document.getElementById('langPickerToggle').classList.remove('open');
    }

    function updateLangPickerMenu() {
      const menu = document.getElementById('langPickerMenu');
      if (!menu || !tracksData.length) return;
      const checkSvg = `<svg class="w-3 h-3 shrink-0" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path stroke-linecap="round" stroke-linejoin="round" d="M5 13l4 4L19 7"/></svg>`;
      const blankSvg = `<span style="width:.75rem;height:.75rem;flex-shrink:0;display:inline-block"></span>`;
      menu.innerHTML =
