        ).join('');
    }

    document.addEventListener('click', e => {
      const wrap = document.getElementById('langPickerWrap');
      if (wrap && !wrap.classList.contains('hidden') && !wrap.contains(e.target)) closeLangPicker();
    });

    // ── Setup Storyboard Hover on JW Player Seekbar ───────────
    let _storyboardCleanups = [];
    function setupStoryboardHover(thumbData) {
      if (!thumbData || !thumbData.url) return;

      _storyboardCleanups.forEach(fn => { try { fn(); } catch(_) {} });
      _storyboardCleanups = [];

      const rawTileWidth = parseInt(thumbData.tileWidth) || 0;
      const rawWidth     = parseInt(thumbData.width) || parseInt(thumbData.tileW) || 0;
      const rawHeight    = parseInt(thumbData.height) || parseInt(thumbData.tileH) || 0;
      const cnt          = parseInt(thumbData.count) || parseInt(thumbData.number) || 0;

      let cols = parseInt(thumbData.cols) || 0;
      let tW = rawWidth;
      let tH = rawHeight;

      if (rawTileWidth > 0 && rawTileWidth <= 50) {
        cols = rawTileWidth;
        if (!tW) tW = 160;
        if (!tH) tH = 90;
      } else if (rawTileWidth > 50) {
        tW = rawTileWidth;
        tH = parseInt(thumbData.tileHeight) || rawHeight || 90;
        cols = cols || Math.max(1, Math.floor((rawWidth || (tW * 10)) / tW));
      } else {
        if (!cols) cols = 10;
        if (!tW) tW = 160;
        if (!tH) tH = 90;
      }

      if (!cnt || !cols || !tW || !tH) return;

      const playerContainer = document.getElementById('jwplayer');
      if (!playerContainer) return;

      const timeSlider = playerContainer.querySelector('.jw-slider-time');
      const timeTip    = playerContainer.querySelector('.jw-time-tip');
      if (!timeSlider || !timeTip) return;

      let _rafId = null;
      let _cachedRect = null;
      let _rectTimer = null;

      const onMouseMove = (e) => {
        if (_rafId) return;
        _rafId = requestAnimationFrame(() => {
          _rafId = null;
          if (!_cachedRect) {
            _cachedRect = timeSlider.getBoundingClientRect();
            clearTimeout(_rectTimer);
            _rectTimer = setTimeout(() => { _cachedRect = null; }, 500);
          }

          if (!_cachedRect || _cachedRect.width <= 0) return;

          const pct = Math.max(0, Math.min(1, (e.clientX - _cachedRect.left) / _cachedRect.width));
          const idx = Math.min(cnt - 1, Math.max(0, Math.floor(pct * cnt)));

          const col = idx % cols;
          const row = Math.floor(idx / cols);
          const x = col * tW;
          const y = row * tH;

          timeTip.classList.add('has-preview-thumb');
          timeTip.style.backgroundImage = `url("${thumbData.url}")`;
          timeTip.style.backgroundPosition = `-${x}px -${y}px`;
          timeTip.style.backgroundRepeat = 'no-repeat';
          timeTip.style.width = `${tW}px`;
          timeTip.style.height = `${tH}px`;
        });
      };

      const onMouseLeave = () => {
        _cachedRect = null;
        if (_rafId) { cancelAnimationFrame(_rafId); _rafId = null; }
        timeTip.classList.remove('has-preview-thumb');
        timeTip.style.backgroundImage = '';
        timeTip.style.backgroundPosition = '';
        timeTip.style.width = '';
        timeTip.style.height = '';
      };

      timeSlider.addEventListener('mousemove', onMouseMove, { passive: true });
      timeSlider.addEventListener('mouseleave', onMouseLeave, { passive: true });

      _storyboardCleanups.push(() => {
        timeSlider.removeEventListener('mousemove', onMouseMove);
        timeSlider.removeEventListener('mouseleave', onMouseLeave);
