    // ── Quality Labels Handler (Fixes portrait & vertical resolutions) ───
    let _settingsClickAttached = false;

    const PORTRAIT_TIER_MAP = {
      '1280p': '720p',
      '852p':  '480p',
      '854p':  '480p',
      '640p':  '360p',
      '426p':  '240p',
      '256p':  '144p',
      '1920p': '1080p',
      '2560p': '1440p',
      '3840p': '2160p'
    };

    // ── HLS buffer configuration for long videos (prevents tab freeze & OOM) ──
    const HLS_BUFFER_CONFIG = {
      enableWorker: true,
      lowLatencyMode: false,
      maxBufferLength: 10,
      maxMaxBufferLength: 20,
      maxBufferSize: 15 * 1024 * 1024,
      backBufferLength: 10,
      maxBufferHole: 0.5,
      highBufferWatchdogPeriod: 2,
      nudgeOffset: 0.1,
      nudgeMaxRetry: 5,
      maxFragLookUpTolerance: 0.25,
      manifestLoadingTimeOut: 10000,
      manifestLoadingMaxRetry: 3,
      levelLoadingTimeOut: 10000,
      levelLoadingMaxRetry: 3,
      fragLoadingTimeOut: 15000,
      fragLoadingMaxRetry: 3
    };

    function refreshQualityLabelsDOM() {
      const container = document.getElementById('jwplayer');
      if (!container) return;

      const items = container.querySelectorAll('.jw-settings-content-item, .jw-auto-label, .jw-settings-topbar-text, .jw-icon-hd .jw-text, .jw-settings-item');
      items.forEach(el => {
        Array.from(el.childNodes).forEach(node => {
          if (node.nodeType === Node.TEXT_NODE && /\d+p/i.test(node.nodeValue)) {
            let val = node.nodeValue;
            for (const [bad, good] of Object.entries(PORTRAIT_TIER_MAP)) {
              val = val.replace(new RegExp(`\\b${bad}\\b`, 'g'), good);
            }
            if (node.nodeValue !== val) {
              node.nodeValue = val;
            }
          }
        });
      });
    }

    function setupQualityHandler() {
      if (!jwInstance) return;

      try {
        jwInstance.on('levels', (e) => {
          if (e && Array.isArray(e.levels)) {
            e.levels.forEach(lvl => {
              if (lvl && lvl.label) {
                for (const [bad, good] of Object.entries(PORTRAIT_TIER_MAP)) {
                  if (lvl.label.includes(bad)) {
                    lvl.label = lvl.label.replace(bad, good);
                  }
                }
              }
            });
          }
        });
      } catch (_) {}

      const playerContainer = document.getElementById('jwplayer');
      if (playerContainer && !_settingsClickAttached) {
        _settingsClickAttached = true;
        playerContainer.addEventListener('click', (e) => {
          if (e.target && e.target.closest && e.target.closest('.jw-settings-content-item, .jw-icon-settings, .jw-settings-submenu, .jw-settings-menu')) {
            setTimeout(refreshQualityLabelsDOM, 30);
            setTimeout(refreshQualityLabelsDOM, 150);
          }
        }, { passive: true });
      }
    }

    // ── Init JW Player ───────────────────────────────────────
    async function initPlayer(data) {
      videoData = data;

      const isMp4 = data.type === 'mp4' || !!data._nothls;
      const streamUrl = (isMp4
        ? (data.stream_url || data.mp4 || data.url || data.video_url || data.orignalmp4 || data.hls_url)
        : (data.hls_url || data.stream_url || data.url || data.video_url || '')) || '';

      const playerTracks = [];

      // Subtitles
      if (data.subtitles && Array.isArray(data.subtitles) && data.subtitles.length) {
        data.subtitles.forEach((s, idx) => {
          playerTracks.push({
            file: s.url,
            label: s.name || (s.language ? s.language.toUpperCase() : `Track ${idx + 1}`),
            kind: 'captions',
            default: !!(s.default || idx === 0)
          });
        });
      }

      const jwConfig = {
        file: streamUrl,
        type: isMp4 ? 'mp4' : 'hls',
        image: data.thumbnail || '',
        width: '100%',
        aspectratio: '16:9',
        autostart: false,
        preload: 'none',
        stretching: 'uniform',
        playbackRateControls: [0.5, 0.75, 1, 1.25, 1.5, 2],
        tracks: playerTracks,
        hlsjsConfig: HLS_BUFFER_CONFIG
      };

      try {
        if (jwplayer('jwplayer')) {
          jwplayer('jwplayer').remove();
        }
      } catch (_) {}

      jwInstance = jwplayer('jwplayer').setup(jwConfig);

      // Setup Quality Labels Handler
      setupQualityHandler();

      // Setup Storyboard seekbar hover previews
      if (data.preview_thums && data.preview_thums.url) {
        const attachThumbs = () => setupStoryboardHover(data.preview_thums);
        jwInstance.on('ready', attachThumbs);
        jwInstance.once('play', attachThumbs);
        setTimeout(attachThumbs, 400);
        setTimeout(attachThumbs, 1200);
      }

      // CC Button sync
      const btnSub = document.getElementById('btnSubtitle');
      const btnSubLabel = document.getElementById('btnSubtitleLabel');
      if (data.subtitles && data.subtitles.length) {
        if (btnSub) { btnSub.classList.remove('hidden'); btnSub.style.opacity = '1'; }
        if (btnSubLabel) btnSubLabel.textContent = 'CC: ON';
      } else if (btnSub) {
        btnSub.classList.add('hidden');
      }

      jwInstance.on('captionsChanged', (e) => {
        const isOn = e && e.currentTrack > 0;
        if (btnSubLabel) btnSubLabel.textContent = isOn ? 'CC: ON' : 'CC: OFF';
        if (btnSub) btnSub.style.opacity = isOn ? '1' : '0.45';
      });

      // Language track switcher (multi-mode)
      if (data.tracks && data.tracks.length > 1) {
        document.getElementById('langPickerWrap').classList.remove('hidden');
        updateLangPickerMenu();
      } else {
        document.getElementById('langPickerWrap').classList.add('hidden');
      }

      jwInstance.on('error', (err) => {
        console.error('JW Player error:', err);
        showToast('Playback error: ' + (err.message || 'Please refresh the page.'), 'error');
      });

      // Meta badges
      if (data.size) {
        const el = document.getElementById('videoSize');
        el.querySelector('span').textContent = formatBytes(data.size);
        el.classList.remove('hidden');
      }

      if (data.views !== undefined) {
        const el = document.getElementById('videoViews');
        el.querySelector('span').textContent = Number(data.views).toLocaleString() + ' views';
        el.classList.remove('hidden');
      }

      // Embed code
      document.getElementById('embedCode').value =
        `<iframe src="https://anonmp4.art/embed/ESuKsItGgV4rMAE" width="640" height="360" frameborder="0" allowfullscreen allow="autoplay; fullscreen; picture-in-picture"></iframe>`;

      show('playerState');
      const nothlsEl = document.getElementById('nothlsBanner');
      if (nothlsEl) {
        if (data._nothls) {
          nothlsEl.classList.remove('hidden');
        } else {
          nothlsEl.classList.add('hidden');
        }
      }
    }

    // ── Fetch raw video JSON from an API URL ────────────────
    async function fetchVideoJSON(apiUrl) {
      const res  = await fetch(apiUrl);
      const json = await res.json().catch(() => ({}));
      if (!res.ok || json.success === false || json.status === 'error') {
        if ((json.type === 'nothls' || json.type === 'mp4') && (json.orignalmp4 || json.mp4 || json.url || json.stream_url)) {
          return {
            _nothls: json.type === 'nothls',
            type: 'mp4',
            orignalmp4: json.orignalmp4 || json.mp4 || json.url || json.stream_url,
            stream_url: json.orignalmp4 || json.mp4 || json.url || json.stream_url,
            thumbnail: json.thumbnail || ''
          };
        }
        const err = new Error(json.error || json.message || `Request failed (${res.status})`);
        err.type = json.type || null;
        throw err;
      }
      const hasMedia = json.hls || json.mp4 || json.url || json.stream_url || json.video_url || json.file || json.orignalmp4 || json._nothls || json.type === 'mp4';
      if (json.status !== 'ok' || !hasMedia) {
        throw new Error('Invalid response from server.');
      }
      return json;
    }

    // ── Map raw JSON → initPlayer data shape ─────────────────
    function mapJsonToData(json, title) {
      const isNotHls = !!json._nothls || json.type === 'nothls';
      const streamUrl = json.mp4 || json.url || json.stream_url || json.video_url || json.file || json.orignalmp4 || json.hls || '';
      const isExplicitMp4 = json.type === 'mp4' || isNotHls;
      const isExplicitHls = json.type === 'hls';
      const isHls = isExplicitHls || (!isExplicitMp4 && (Boolean(json.hls && !json.mp4) || streamUrl.includes('.m3u8') || streamUrl.includes('/hls/')));
      const resolvedType = isHls ? 'hls' : 'mp4';

      if (isNotHls) {
        return {
          _nothls:       true,
          type:          'mp4',
          hls_url:       null,
          stream_url:    json.orignalmp4 || streamUrl,
          thumbnail:     json.thumbnail || '',
          duration:      null,
          title:         title || 'Video',
          preview_thums: null,
          subtitles:     [],
        };
      }
      const _pt = json.preview_thums;
      const thumb = Array.isArray(_pt) && _pt.length ? _pt[0]
                  : (_pt && typeof _pt === 'object' && !Array.isArray(_pt) && _pt.url) ? _pt
                  : null;
      const subtitles = Array.isArray(json.subtitles)
        ? json.subtitles
            .filter(s => s.url)
            .map((s, i) => ({
              url:     s.url,
              name:    s.language ? s.language.toUpperCase() : `Track ${i + 1}`,
              default: s.isDefault || i === 0,
            }))
        : [];
      return {
        type:          resolvedType,
        _nothls:       false,
        hls_url:       resolvedType === 'hls' ? (json.hls || streamUrl) : null,
        stream_url:    streamUrl,
        thumbnail:     json.thumbnail || '',
        duration:      json.duration ? Number(json.duration) : null,
        title:         title || 'Video',
        preview_thums: thumb,
        subtitles,
      };
    }

    // ── Switch language track (multi-mode) ───────────────────
    async function switchToTrack(targetIndex) {
      if (targetIndex === currentTrackIndex || !tracksData.length) return;

      const tried = new Set([currentTrackIndex]);
      let idx = targetIndex;

      while (true) {
        const track = tracksData[idx];
        showPlayerNotice(`Loading "${track.track_name}"…`, 'info');
        try {
          if (!track._cachedData) {
            const json = await fetchVideoJSON(track.track_url);
            const mapped = mapJsonToData(json, track.track_name);
            track.type        = mapped.type;
            track.hls_url     = mapped.hls_url;
            track.stream_url  = mapped.stream_url;
            track.thumbnail   = mapped.thumbnail;
            track.duration    = mapped.duration;
            track._cachedData = mapped;
          }
          currentTrackIndex = idx;

          const savedPos = jwInstance ? jwInstance.getPosition() : 0;
          const wasPlaying = jwInstance ? (jwInstance.getState() === 'playing') : false;

          const isTrackMp4 = track._cachedData.type === 'mp4' || !!track._cachedData._nothls;
          const newStreamUrl = isTrackMp4
            ? (track._cachedData.stream_url || track.stream_url || track._cachedData.hls_url || track.hls_url || '')
            : (track.hls_url || track._cachedData.hls_url || track._cachedData.stream_url || '');

          const newTracks = [];
          if (track._cachedData.subtitles && track._cachedData.subtitles.length) {
            track._cachedData.subtitles.forEach((s, i) => {
              newTracks.push({
                file: s.url,
                label: s.name || s.language || `Track ${i + 1}`,
                kind: 'captions',
                default: s.default || i === 0
              });
            });
          }

          const thumbData = track._cachedData?.preview_thums || videoData?.preview_thums;
          const loadItem = {
            file: newStreamUrl,
            type: isTrackMp4 ? 'mp4' : 'hls',
            image: track.thumbnail || videoData?.thumbnail || '',
            tracks: newTracks,
            preload: 'none',
            hlsjsConfig: HLS_BUFFER_CONFIG
          };

          jwInstance.load([loadItem]);
          setupQualityHandler();

          if (thumbData && thumbData.url) {
            setupStoryboardHover(thumbData);
          }

          if (savedPos > 0) {
            jwInstance.once('play', () => {
              jwInstance.seek(savedPos);
            });
          }
          if (wasPlaying) {
            jwInstance.play();
          }

          updateLangPickerMenu();
          showPlayerNotice(`▶ ${track.track_name}`, 'success');
          return;
        } catch (err) {
          tried.add(idx);
          const next = tracksData.findIndex((_, i) => !tried.has(i));
          if (next === -1) {
            showPlayerNotice(`"${track.track_name}" failed. No more tracks.`, 'error');
            showToast(`"${track.track_name}" failed. No more tracks available.`, 'error');
            return;
          }
          showPlayerNotice(`"${track.track_name}" failed — trying next…`, 'error');
          idx = next;
        }
      }
    }

    // ── Try loading tracks starting from startIndex (multi) ──
    async function tryLoadTrackFrom(startIndex) {
      for (let i = startIndex; i < tracksData.length; i++) {
        try {
          const json = await fetchVideoJSON(tracksData[i].track_url);
          const mapped = mapJsonToData(json, tracksData[i].track_name);
          tracksData[i].type        = mapped.type;
          tracksData[i].hls_url     = mapped.hls_url;
          tracksData[i].stream_url  = mapped.stream_url;
          tracksData[i].thumbnail   = mapped.thumbnail;
          tracksData[i].duration    = mapped.duration;
          tracksData[i]._cachedData = mapped;
          currentTrackIndex = i;
          const data = {
            ...mapped,
            tracks:            tracksData,
            currentTrackIndex: i,
          };
          await initPlayer(data);
          return;
        } catch (err) {
          const hasMore = i + 1 < tracksData.length;
          showToast(
            `Track "${tracksData[i].track_name}" failed.${hasMore ? ' Trying next…' : ' No more tracks.'}`,
            'error'
          );
          if (!hasMore) throw new Error('All tracks failed to load.');
        }
      }
    }

    // ── Load video info ──────────────────────────────────────
    async function loadVideo() {
      if (VIDEO_STATUS === 'not_found') {
        document.getElementById('errorTitle').textContent = 'Video Not Found';
