      document.body.appendChild(ta);
      ta.focus(); ta.select();
      try { document.execCommand('copy'); showToast('Link copied!', 'success'); }
      catch (_) { showToast('Could not copy — please copy manually.', 'error'); }
      document.body.removeChild(ta);
